input.new_string:
function trim(s) {
  return s.trim();
}

// Separators are anything outside [a-z0-9], so non-ASCII letters are dropped
// rather than preserved -- the output is meant to be URL-safe ASCII.
function slugify(s) {
  return s
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { trim, slugify };

