input.new_string:
const { trim, slugify } = require('../src/str');

test('trim', () => {
  assert.strictEqual(trim('  a  '), 'a');
});

test('slugify lowercases', () => {
  assert.strictEqual(slugify('Hello'), 'hello');
});

test('slugify collapses runs of non-alphanumerics to one dash', () => {
  assert.strictEqual(slugify('hello   world'), 'hello-world');
  assert.strictEqual(slugify('a -- b__c'), 'a-b-c');
});

test('slugify strips leading and trailing dashes', () => {
  assert.strictEqual(slugify('  Hello, World!  '), 'hello-world');
  assert.strictEqual(slugify('---x---'), 'x');
});

test('slugify keeps digits', () => {
  assert.strictEqual(slugify('Issue 6: add slugify'), 'issue-6-add-slugify');
});

test('slugify returns empty string when nothing survives', () => {
  assert.strictEqual(slugify(''), '');
  assert.strictEqual(slugify('   '), '');
  assert.strictEqual(slugify('!!!'), '');
});

test('slugify treats non-ASCII letters as separators', () => {
  assert.strictEqual(slugify('café au lait'), 'caf-au-lait');
});

